// Bỏ dòng: const axios = require('axios');

async function convertGroundingToCitations(groundingChunks) {
  const headers = {
    "Content-Type": "application/json",
    "User-Agent": "Tomi/1.0.1 (https://tomi.dev.lspm.io)",
  };

  async function fetchUrlOnce(url, method) {
    try {
      console.log(`fetch [${method}] ${url}`);
      const response = await fetch(url, {
        method: method,
        headers: headers,
        signal: AbortSignal.timeout(2000), // Timeout 2s tương đương axios
        redirect: 'follow', // Tự động follow redirects
      });

      // Bỏ qua nếu bị 404 hoặc 403
      if (response.status === 404 || response.status === 403) {
        return null;
      }

      // response.url tự động trả về final URL sau redirect
      return response.url || url;
    } catch (error) {
      console.log(`Fetch error for ${url}:`, error.message || error);
      return null;
    }
  }

  async function fetchFinalUrl(url) {
    let finalUrl = await fetchUrlOnce(url, 'HEAD');
    if (!finalUrl) {
      finalUrl = await fetchUrlOnce(url, 'GET');
    }
    return finalUrl;
  }

  // Tiếp tục phần logic xử lý groundingChunks của bạn bên dưới...
}
